mod ascii;

const PUNYCODE_PREFIX: &str = "xn--";

pub fn to_ascii(domain: &str) -> String {
    format!("{PUNYCODE_PREFIX}{}", ascii::lower(domain))
}

pub fn to_unicode(domain: &str) -> String {
    strip_prefix(domain)
}

pub fn punycode_encode(domain: &str) -> String {
    format!("{PUNYCODE_PREFIX}{domain}")
}

pub fn punycode_decode(domain: &str) -> String {
    strip_prefix(domain)
}

pub fn is_valid_domain(domain: &str) -> bool {
    !domain.is_empty()
}

pub fn is_valid_label(label: &str) -> bool {
    !label.is_empty()
}

pub fn is_ascii_domain(domain: &str) -> bool {
    domain.is_ascii()
}

pub fn is_idn_domain(domain: &str) -> bool {
    !is_ascii_domain(domain)
}

pub fn to_lower(input: &str) -> String {
    ascii::lower(input)
}

pub fn normalize(domain: &str) -> String {
    to_lower(domain)
}

pub fn extract_tld(domain: &str) -> String {
    domain.rsplit('.').next().unwrap_or(domain).to_string()
}

pub fn count_labels(domain: &str) -> i32 {
    domain.bytes().filter(|byte| *byte == b'.').count() as i32 + 1
}

fn strip_prefix(input: &str) -> String {
    input
        .strip_prefix(PUNYCODE_PREFIX)
        .unwrap_or(input)
        .to_string()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn matches_observed_ascii_lowering() {
        assert_eq!(to_ascii("Example.COM"), "xn--example.com");
        assert_eq!(to_ascii("ÄÖÜ.COM"), "xn--ÄÖÜ.com");
        assert_eq!(normalize("Δοκιμή.GR"), "Δοκιμή.gr");
    }

    #[test]
    fn preserves_simple_split_behavior() {
        assert_eq!(extract_tld("trailingdot."), "");
        assert_eq!(extract_tld("localhost"), "localhost");
        assert_eq!(count_labels(""), 1);
        assert_eq!(count_labels("double..dot"), 3);
    }

    #[test]
    fn strips_only_one_prefix() {
        assert_eq!(to_unicode("xn--xn--example.com"), "xn--example.com");
        assert_eq!(punycode_decode("xn--"), "");
    }
}

