#[path = "src/lib.rs"]
mod crate_lib;

use crate_lib::idna;
use std::env;

fn main() {
    let domain = env::args()
        .nth(1)
        .unwrap_or_else(|| "multi.level.domain.name.test".to_string());

    let result1 = idna::to_ascii(&domain);
    let result2 = idna::to_unicode(&result1);
    let result3 = idna::punycode_encode(&domain);
    let result4 = idna::punycode_decode(&result3);
    let result5 = idna::is_valid_domain(&domain);
    let result6 = idna::is_valid_label("testlabel");
    let result7 = idna::is_ascii_domain(&domain);
    let result8 = idna::is_idn_domain(&domain);
    let result9 = idna::to_lower("MIXEDCase");
    let result10 = idna::normalize(&domain);
    let result11 = idna::extract_tld(&domain);
    let result12 = idna::count_labels(&domain);

    println!("{result1}");
    println!("{result2}");
    println!("{result3}");
    println!("{result4}");
    println!("{}", i32::from(result5));
    println!("{}", i32::from(result6));
    println!("{}", i32::from(result7));
    println!("{}", i32::from(result8));
    println!("{result9}");
    println!("{result10}");
    println!("{result11}");
    println!("{result12}");
}
